dd(\"--nested-visible\");\r\n        this.nested?.classList.add(\"--visible\");\r\n      });\r\n    });\r\n  }\r\n\r\n  private hideNestedSelect(): boolean {\r\n    if (!this.nested || this.nested.hidden) return false;\r\n\r\n    this.nested.classList.remove(\"--visible\");\r\n    this.portal?.classList.remove(\"--nested-visible\");\r\n    window.setTimeout(() => {\r\n      if (!this.nested || !this.nestedBody) return;\r\n      this.nested.hidden = true;\r\n      this.nestedBody.innerHTML = \"\";\r\n      this.nestedState = null;\r\n    }, 260);\r\n\r\n    this.closeButton?.focus();\r\n    return true;\r\n  }\r\n\r\n  private renderNestedSelectOptions(): void {\r\n    if (!this.nestedBody || !this.nestedState) return;\r\n\r\n    this.nestedBody.innerHTML = \"\";\r\n\r\n    const optionsList = document.createElement(\"div\");\r\n    optionsList.className = \"mobile-portal__options\";\r\n    optionsList.setAttribute(\"role\", \"listbox\");\r\n\r\n    this.nestedState.options.forEach((option) => {\r\n      const optionButton = document.createElement(\"button\");\r\n      optionButton.type = \"button\";\r\n      optionButton.className = \"mobile-portal__option\";\r\n      optionButton.textContent = option.label;\r\n      optionButton.dataset.value = option.value;\r\n      optionButton.setAttribute(\"role\", \"option\");\r\n      optionButton.setAttribute(\"aria-selected\", String(this.nestedState?.draftValue === option.value));\r\n\r\n      if (this.nestedState?.draftValue === option.value) {\r\n        optionButton.classList.add(\"--selected\");\r\n      }\r\n\r\n      if (option.disabled) {\r\n        optionButton.disabled = true;\r\n      }\r\n\r\n      optionButton.addEventListener(\"click\", () => {\r\n        if (!this.nestedState || option.disabled) return;\r\n        this.nestedState.draftValue = option.value;\r\n        this.renderNestedSelectOptions();\r\n      });\r\n\r\n      optionsList.appendChild(optionButton);\r\n    });\r\n\r\n    this.nestedBody.appendChild(optionsList);\r\n  }\r\n}\r\n\r\nexport const mobilePortal = new MobilePortal();\r\n","// ============================================\r\n// FORM HANDLERS - Dostosowane do istniejących stylów SCSS\r\n// ============================================\r\n\r\nimport { mobilePortal } from \"./mobile-portal\";  \r\n \r\ntype InputElement = HTMLInputElement | HTMLTextAreaElement;\r\nlet isOutsideClickHandlerBound = false;\r\nlet isPortalContentListenerBound = false;\r\n\r\n/**\r\n * Znajduje najbliższy element InputWrap\r\n */\r\nconst findInputWrap = (element: HTMLElement): HTMLElement | null => {\r\n  let wrap = element.closest<HTMLElement>('.InputWrap');\r\n  if (wrap) return wrap;\r\n  \r\n  let parent = element.parentElement;\r\n  while (parent) {\r\n    if (parent.classList.contains('InputWrap')) {\r\n      return parent;\r\n    }\r\n    parent = parent.parentElement;\r\n  }\r\n  \r\n  return null;\r\n};\r\n\r\n/**\r\n * Walidacja email\r\n */\r\nconst isValidEmail = (email: string): boolean => {\r\n  const pattern = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/;\r\n  return pattern.test(email);\r\n};\r\n\r\n/**\r\n * Walidacja telefonu\r\n */\r\nconst isValidPhone = (phone: string): boolean => {\r\n  const pattern = /^[\\+]?[(]?[0-9]{1,4}[)]?[-\\s\\.]?[(]?[0-9]{1,4}[)]?[-\\s\\.]?[0-9]{1,9}$/;\r\n  return pattern.test(phone.replace(/\\s/g, ''));\r\n};\r\n\r\n/**\r\n * Aktualizuje stan InputWrap\r\n */\r\nconst updateInputWrapState = (\r\n  inputWrap: HTMLElement,\r\n  state: 'focus' | 'active' | 'error',\r\n  add: boolean\r\n): void => {\r\n  const className = `--${state}`;\r\n  \r\n  if (add) {\r\n    inputWrap.classList.add(className);\r\n  } else {\r\n    inputWrap.classList.remove(className);\r\n  }\r\n  \r\n  // Aktualizuj placeholder przy focus\r\n  if (state === 'focus') {\r\n    const placeholder = inputWrap.querySelector<HTMLElement>('.InputPlaceholder');\r\n    if (placeholder) {\r\n      if (add) {\r\n        placeholder.classList.add('--focus');\r\n      } else {\r\n        placeholder.classList.remove('--focus');\r\n      }\r\n    }\r\n  }\r\n};\r\n\r\n/**\r\n * Waliduje input\r\n */\r\nconst validateInput = (input: HTMLInputElement, inputWrap: HTMLElement): boolean => {\r\n  const value = input.value.trim();\r\n  const type = input.type;\r\n  const required = input.hasAttribute('required');\r\n  const minLength = parseInt(input.getAttribute('minlength') || '0', 10);\r\n  \r\n  // Pole puste\r\n  if (value === '') {\r\n    if (required) {\r\n      updateInputWrapState(inputWrap, 'error', true);\r\n      updateInputWrapState(inputWrap, 'active', false);\r\n      return false;\r\n    }\r\n    // Pole opcjonalne i puste\r\n    updateInputWrapState(inputWrap, 'error', false);\r\n    updateInputWrapState(inputWrap, 'active', false);\r\n    return true;\r\n  }\r\n  \r\n  // Minimalna długość\r\n  if (minLength > 0 && value.length < minLength) {\r\n    updateInputWrapState(inputWrap, 'error', true);\r\n    updateInputWrapState(inputWrap, 'active', false);\r\n    return false;\r\n  }\r\n  \r\n  // Walidacja typu\r\n  let isValid = true;\r\n  \r\n  switch (type) {\r\n    case 'email':\r\n      isValid = isValidEmail(value);\r\n      break;\r\n    case 'tel':\r\n      isValid = isValidPhone(value);\r\n      break;\r\n    case 'url':\r\n      try {\r\n        new URL(value);\r\n        isValid = true;\r\n      } catch {\r\n        isValid = false;\r\n      }\r\n      break;\r\n    default:\r\n      isValid = true;\r\n  }\r\n  \r\n  if (isValid) {\r\n    updateInputWrapState(inputWrap, 'error', false);\r\n    updateInputWrapState(inputWrap, 'active', true);\r\n  } else {\r\n    updateInputWrapState(inputWrap, 'error', true);\r\n    updateInputWrapState(inputWrap, 'active', false);\r\n  }\r\n  \r\n  return isValid;\r\n};\r\n\r\n/**\r\n * Waliduje textarea\r\n */\r\nconst validateTextarea = (textarea: HTMLTextAreaElement, inputWrap: HTMLElement): boolean => {\r\n  const value = textarea.value.trim();\r\n  const required = textarea.hasAttribute('required');\r\n  const minLength = parseInt(textarea.getAttribute('minlength') || '0', 10);\r\n  \r\n  if (value === '') {\r\n    if (required) {\r\n      updateInputWrapState(inputWrap, 'error', true);\r\n      updateInputWrapState(inputWrap, 'active', false);\r\n      return false;\r\n    }\r\n    updateInputWrapState(inputWrap, 'error', false);\r\n    updateInputWrapState(inputWrap, 'active', false);\r\n    return true;\r\n  }\r\n  \r\n  if (minLength > 0 && value.length < minLength) {\r\n    updateInputWrapState(inputWrap, 'error', true);\r\n    updateInputWrapState(inputWrap, 'active', false);\r\n    return false;\r\n  }\r\n  \r\n  updateInputWrapState(inputWrap, 'error', false);\r\n  updateInputWrapState(inputWrap, 'active', true);\r\n  return true;\r\n};\r\n\r\n/**\r\n * Inicjalizuje inputy\r\n */\r\nconst initInputHandlers = (root: ParentNode = document): void => {\r\n  const inputs = root.querySelectorAll<HTMLInputElement>(\r\n    'input[type=\"text\"], input[type=\"email\"], input[type=\"tel\"], input[type=\"password\"], input[type=\"url\"], input[type=\"number\"]'\r\n  );\r\n  \r\n  inputs.forEach((input) => {\r\n    if (input.closest('[data-mobile-portal-source]')) return;\r\n    if (input.dataset.formInitialized === 'true') return;\r\n\r\n    const inputWrap = findInputWrap(input);\r\n    if (!inputWrap) return;\r\n    \r\n    // Focus\r\n    input.addEventListener('focus', () => {\r\n      updateInputWrapState(inputWrap, 'focus', true);\r\n    });\r\n    \r\n    // Blur\r\n    input.addEventListener('blur', () => {\r\n      // Usuń focus tylko jeśli pole puste\r\n      if (input.value.trim() === '') {\r\n        updateInputWrapState(inputWrap, 'focus', false);\r\n      }\r\n      validateInput(input, inputWrap);\r\n    });\r\n    \r\n    // Input - live validation (usuwa error podczas pisania)\r\n    input.addEventListener('input', () => {\r\n      if (inputWrap.classList.contains('--error')) {\r\n        validateInput(input, inputWrap);\r\n      }\r\n    });\r\n    \r\n    // Stan początkowy (autofill)\r\n    if (input.value.trim() !== '') {\r\n      validateInput(input, inputWrap);\r\n      updateInputWrapState(inputWrap, 'focus', true);\r\n    }\r\n\r\n    input.dataset.formInitialized = 'true';\r\n  });\r\n};\r\n\r\n/**\r\n * Inicjalizuje textareas\r\n */\r\nconst initTextareaHandlers = (root: ParentNode = document): void => {\r\n  const textareas = root.querySelectorAll<HTMLTextAreaElement>('textarea');\r\n  \r\n  textareas.forEach((textarea) => {\r\n    if (textarea.closest('[data-mobile-portal-source]')) return;\r\n    if (textarea.dataset.formInitialized === 'true') return;\r\n\r\n    const inputWrap = findInputWrap(textarea);\r\n    if (!inputWrap) return;\r\n    \r\n    textarea.addEventListener('focus', () => {\r\n      updateInputWrapState(inputWrap, 'focus', true);\r\n    });\r\n  \r\n    textarea.addEventListener('blur', () => {\r\n      if (textarea.value.trim() === '') {\r\n        updateInputWrapState(inputWrap, 'focus', false);\r\n      }\r\n      validateTextarea(textarea, inputWrap);\r\n    });\r\n    \r\n    textarea.addEventListener('input', () => {\r\n      if (inputWrap.classList.contains('--error')) {\r\n        validateTextarea(textarea, inputWrap);\r\n      }\r\n    });\r\n    \r\n    if (textarea.value.trim() !== '') {\r\n      validateTextarea(textarea, inputWrap);\r\n      updateInputWrapState(inputWrap, 'focus', true);\r\n    }\r\n\r\n    textarea.dataset.formInitialized = 'true';\r\n  });\r\n};\r\n\r\n/**\r\n * Inicjalizuje custom selects\r\n */\r\nconst syncCustomSelectState = (\r\n  select: HTMLSelectElement,\r\n  replacementDiv: HTMLElement,\r\n  span: HTMLElement,\r\n): void => {\r\n  const selectedOption = select.options[select.selectedIndex];\r\n  const placeholder = select.getAttribute('placeholder') || select.getAttribute('data-placeholder') || '';\r\n\r\n  span.textContent = selectedOption?.textContent || placeholder;\r\n\r\n  replacementDiv\r\n    .querySelectorAll<HTMLElement>('.select-option')\r\n    .forEach((optionElement, index) => {\r\n      optionElement.classList.toggle('--active', index === select.selectedIndex);\r\n    });\r\n\r\n  if (select.value !== '') {\r\n    replacementDiv.classList.add('--active');\r\n  } else {\r\n    replacementDiv.classList.remove('--active');\r\n  }\r\n};\r\n\r\nconst initCustomSelects = (root: ParentNode = document): void => {\r\n  const selects = root.querySelectorAll<HTMLSelectElement>('select');\r\n  \r\n  selects.forEach((select) => {\r\n    if (select.closest('[data-mobile-portal-source]')) return;\r\n    if (select.dataset.customSelectInitialized === 'true') return;\r\n\r\n    // Sprawdź czy już zastąpiony\r\n    if (select.style.display === 'none' && select.previousElementSibling?.classList.contains('custom-select')) {\r\n      select.dataset.customSelectInitialized = 'true';\r\n      return;\r\n    }\r\n    \r\n    const replacementDiv = document.createElement('div');\r\n    replacementDiv.className = 'custom-select';\r\n    \r\n    const selectedDiv = document.createElement('div');\r\n    selectedDiv.className = 'select-selected';\r\n    \r\n    const span = document.createElement('span');\r\n    const placeholder = select.getAttribute('placeholder') || select.getAttribute('data-placeholder');\r\n    span.textContent = placeholder || select.options[select.selectedIndex]?.textContent || '';\r\n    selectedDiv.appendChild(span);\r\n    \r\n    if (select.selectedIndex > 0) {\r\n      replacementDiv.classList.add('--active');\r\n    }\r\n    \r\n    replacementDiv.appendChild(selectedDiv);\r\n    \r\n    const optionsContainer = document.createElement('div');\r\n    optionsContainer.className = 'select-options-container';\r\n    \r\n    Array.from(select.options).forEach((option, index) => {\r\n      const optionDiv = document.createElement('div');\r\n      optionDiv.textContent = option.textContent || '';\r\n      optionDiv.dataset.value = option.value;\r\n      optionDiv.className = 'select-option';\r\n      \r\n      if (select.selectedIndex === index) {\r\n        optionDiv.classList.add('--active');\r\n      }\r\n      \r\n      optionDiv.addEventListener('click', () => {\r\n        if (mobilePortal.isEnabled()) {\r\n          return;\r\n        }\r\n\r\n        optionsContainer.querySelectorAll('.select-option').forEach((opt) => {\r\n          opt.classList.remove('--active');\r\n        });\r\n        \r\n        optionDiv.classList.add('--active');\r\n        select.value = optionDiv.dataset.value || '';\r\n        select.dispatchEvent(new Event('change', { bubbles: true }));\r\n        span.textContent = optionDiv.textContent;\r\n        \r\n        if (select.selectedIndex > 0) {\r\n          replacementDiv.classList.add('--active');\r\n        } else {\r\n          replacementDiv.classList.remove('--active');\r\n        }\r\n        \r\n        replacementDiv.classList.remove('--show');\r\n        optionsContainer.classList.remove('--show');\r\n      });\r\n      \r\n      optionsContainer.appendChild(optionDiv);\r\n    });\r\n    \r\n    replacementDiv.appendChild(optionsContainer);\r\n    \r\n    selectedDiv.addEventListener('click', (event) => {\r\n      event.stopPropagation();\r\n\r\n      if (mobilePortal.isEnabled()) {\r\n        mobilePortal.openSelect(select, selectedDiv);\r\n        return;\r\n      }\r\n      \r\n      // Zamknij inne selecty\r\n      document.querySelectorAll('.custom-select.--show').forEach((openSelect) => {\r\n        if (openSelect !== replacementDiv) {\r\n          openSelect.classList.remove('--show');\r\n          openSelect.querySelector('.select-options-container')?.classList.remove('--show');\r\n        }\r\n      });\r\n      \r\n      replacementDiv.classList.toggle('--show');\r\n      optionsContainer.classList.toggle('--show');\r\n    });\r\n    \r\n    select.parentNode?.insertBefore(replacementDiv, select);\r\n    select.style.display = 'none';\r\n    select.addEventListener('change', () => {\r\n      syncCustomSelectState(select, replacementDiv, span);\r\n    });\r\n    syncCustomSelectState(select, replacementDiv, span);\r\n    select.dataset.customSelectInitialized = 'true';\r\n  });\r\n};\r\n\r\n/**\r\n * Zamyka selecty po kliknięciu poza\r\n */\r\nconst initOutsideClickHandler = (): void => {\r\n  if (isOutsideClickHandlerBound) return;\r\n  isOutsideClickHandlerBound = true;\r\n\r\n  document.addEventListener('click', (e: MouseEvent) => {\r\n    const target = e.target as Node;\r\n    \r\n    document.querySelectorAll<HTMLElement>('.select-options-container.--show').forEach((container) => {\r\n      const customSelect = container.parentElement;\r\n      \r\n      if (customSelect && !customSelect.contains(target)) {\r\n        container.classList.remove('--show');\r\n        customSelect.classList.remove('--show');\r\n      }\r\n    });\r\n  });\r\n};\r\n\r\n/**\r\n * Waliduje cały formularz\r\n */\r\nexport const validateForm = (form: HTMLFormElement): boolean => {\r\n  let isValid = true;\r\n  \r\n  form.querySelectorAll<HTMLInputElement>(\r\n    'input[type=\"text\"], input[type=\"email\"], input[type=\"tel\"], input[type=\"password\"], input[type=\"url\"]'\r\n  ).forEach((input) => {\r\n    const inputWrap = findInputWrap(input);\r\n    if (inputWrap && !validateInput(input, inputWrap)) {\r\n      isValid = false;\r\n    }\r\n  });\r\n  \r\n  form.querySelectorAll<HTMLTextAreaElement>('textarea').forEach((textarea) => {\r\n    const inputWrap = findInputWrap(textarea);\r\n    if (inputWrap && !validateTextarea(textarea, inputWrap)) {\r\n      isValid = false;\r\n    }\r\n  });\r\n  \r\n  return isValid;\r\n};\r\n\r\n/**\r\n * Główna funkcja init\r\n */\r\nconst initPortalContentListener = (): void => {\r\n  if (isPortalContentListenerBound) return;\r\n  isPortalContentListenerBound = true;\r\n\r\n  document.addEventListener('mobileportal:content-ready', (event: Event) => {\r\n    const customEvent = event as CustomEvent<{ root?: ParentNode }>;\r\n    const root = customEvent.detail?.root;\r\n    if (!root) return;\r\n\r\n    initFormHandlers(root);\r\n  });\r\n};\r\n\r\nexport const initFormHandlers = (root: ParentNode = document): void => {\r\n  initInputHandlers(root);\r\n  initTextareaHandlers(root);\r\n  initCustomSelects(root);\r\n  initOutsideClickHandler();\r\n  initPortalContentListener();\r\n  \r\n  // Walidacja przy submicie\r\n  root.querySelectorAll<HTMLFormElement>('form').forEach((form) => {\r\n    if (form.closest('[data-mobile-portal-source]')) return;\r\n    if (form.dataset.formSubmitInitialized === 'true') return;\r\n\r\n    form.addEventListener('submit', (e) => {\r\n      if (!validateForm(form)) {\r\n        e.preventDefault();\r\n        \r\n        // Scroll do pierwszego błędu\r\n        const firstError = form.querySelector('.InputWrap.--error');\r\n        if (firstError) {\r\n          firstError.scrollIntoView({ behavior: 'smooth', block: 'center' });\r\n        }\r\n      }\r\n    });\r\n\r\n    form.dataset.formSubmitInitialized = 'true';\r\n  });\r\n};\r\n","import \"bootstrap/dist/js/bootstrap.bundle.min.js\";\n\ntype BsCollapseCtor = new (\n  el: Element,\n  options?: { toggle?: boolean; parent?: Element | string | null }\r\n) => {\r\n  toggle: () => void;\r\n  show: () => void;\r\n  hide: () => void;\r\n  dispose: () => void;\r\n};\r\n\r\ntype BsModalCtor = new (\r\n  el: Element,\r\n  options?: { backdrop?: boolean | \"static\"; keyboard?: boolean; focus?: boolean }\r\n) => {\r\n  toggle: () => void;\r\n  show: () => void;\r\n  hide: () => void;\r\n  dispose: () => void;\r\n};\r\n\r\ntype BsTabCtor = new (\r\n  el: Element\r\n) => {\r\n  show: () => void;\r\n  dispose: () => void;\r\n};\r\n\r\ntype BsTooltipCtor = new (\n  el: Element,\n  options?: BsTooltipOptions\n) => {\n  show: () => void;\r\n  hide: () => void;\r\n  toggle: () => void;\r\n  dispose: () => void;\r\n  update: () => void;\n};\n\ntype BsTooltipOptions = {\n  animation?: boolean;\n  container?: Element | string | false;\n  customClass?: string;\n  delay?: number | { show: number; hide: number };\n  html?: boolean;\n  offset?: [number, number] | string | ((...args: any[]) => any);\n  placement?: string | ((...args: any[]) => any);\n  title?: string | Element | ((...args: any[]) => any);\n  trigger?: string;\n};\n\ntype BsTooltipInstance = InstanceType<BsTooltipCtor>;\n\ntype BsToastCtor = new (\n  el: Element,\n  options?: { animation?: boolean; autohide?: boolean; delay?: number }\n) => {\r\n  show: () => void;\r\n  hide: () => void;\r\n  dispose: () => void;\n};\n\ntype BootstrapInstanceHelpers<T> = T & {\n  getInstance?: (el: Element) => any;\n  getOrCreateInstance?: (el: Element, options?: any) => any;\n};\r\n\r\nexport const getBootstrap = (): {\r\n  Collapse?: BootstrapInstanceHelpers<BsCollapseCtor>;\r\n  Modal?: BootstrapInstanceHelpers<BsModalCtor>;\r\n  Tab?: BootstrapInstanceHelpers<BsTabCtor>;\r\n  Tooltip?: BootstrapInstanceHelpers<BsTooltipCtor>;\r\n  Toast?: BootstrapInstanceHelpers<BsToastCtor>;\r\n} => {\r\n  return (window as any).bootstrap ?? {};\r\n};\r\n\r\nexport const initBootstrapCollapse = (): void => {\r\n  if (typeof document === \"undefined\") return;\r\n\r\n  const { Collapse } = getBootstrap();\r\n  if (!Collapse) return;\r\n\r\n  document.querySelectorAll<HTMLElement>(\".collapse\").forEach((el) => {\r\n    if (Collapse.getOrCreateInstance) {\r\n      Collapse.getOrCreateInstance(el, { toggle: false });\r\n      return;\r\n    }\r\n\r\n    if (Collapse.getInstance?.(el)) return;\r\n    new Collapse(el, { toggle: false });\r\n  });\r\n};\r\n\r\nexport const initBootstrapModal = (): void => {\r\n  if (typeof document === \"undefined\") return;\r\n\r\n  const { Modal } = getBootstrap();\r\n  if (!Modal) return;\r\n\r\n  document.querySelectorAll<HTMLElement>(\".modal\").forEach((el) => {\r\n    if (Modal.getOrCreateInstance) {\r\n      Modal.getOrCreateInstance(el, {\r\n        backdrop: true,\r\n        keyboard: true,\r\n        focus: true,\r\n      });\r\n      return;\r\n    }\r\n\r\n    if (Modal.getInstance?.(el)) return;\r\n    new Modal(el, {\r\n      backdrop: true,\r\n      keyboard: true,\r\n      focus: true,\r\n    });\r\n  });\r\n};\r\n\r\nexport const initBootstrapTabs = (): void => {\r\n  if (typeof document === \"undefined\") return;\r\n\r\n  const { Tab } = getBootstrap();\r\n  if (!Tab) return;\r\n\r\n  document.querySelectorAll<HTMLElement>('[data-bs-toggle=\"tab\"]').forEach((el) => {\r\n    if (Tab.getOrCreateInstance) {\r\n      Tab.getOrCreateInstance(el);\r\n      return;\r\n    }\r\n\r\n    if (Tab.getInstance?.(el)) return;\r\n    new Tab(el);\r\n  });\r\n};\r\n\r\n\r\nexport const initBootstrapTooltips = (): void => {\n  if (typeof document === \"undefined\") return;\n\n  const { Tooltip } = getBootstrap();\n  if (!Tooltip) return;\n\n  const tooltipElements = document.querySelectorAll<HTMLElement>('[data-bs-toggle=\"tooltip\"]');\n\n  let activeTrigger: HTMLElement | null = null;\n  let activeInstance: BsTooltipInstance | null = null;\n\r\n  const closeActiveTooltip = (): void => {\r\n    if (!activeInstance || !activeTrigger) return;\r\n\r\n    activeInstance.hide();\r\n    activeTrigger.setAttribute(\"aria-expanded\", \"false\");\r\n\r\n    activeInstance = null;\r\n    activeTrigger = null;\r\n  };\r\n\r\n  tooltipElements.forEach((el) => {\n    const contentId = el.getAttribute(\"data-tooltip-content-id\");\r\n    const contentEl = contentId ? document.getElementById(contentId) : null;\r\n\r\n    const tooltipTitle =\r\n      contentEl?.innerHTML.trim() ||\r\n      el.getAttribute(\"data-bs-title\") ||\r\n      el.getAttribute(\"title\") ||\r\n      \"\";\r\n\r\n    if (!tooltipTitle) return;\r\n\r\n    el.setAttribute(\"aria-expanded\", \"false\");\r\n\r\n    const tooltipOptions: BsTooltipOptions = {\n      html: true,\n      container: \"body\",\n      trigger: \"manual\",\n      title: tooltipTitle,\n      offset: [0, 4],\n    };\n\n    const instance = Tooltip.getOrCreateInstance\n      ? Tooltip.getOrCreateInstance(el, tooltipOptions)\n      : new Tooltip(el, tooltipOptions);\n\r\n    el.addEventListener(\"click\", (event) => {\n      event.preventDefault();\r\n      event.stopPropagation();\r\n\r\n      const isSameTooltipOpen = activeTrigger === el;\r\n\r\n      if (activeInstance && activeTrigger && activeTrigger !== el) {\r\n        closeActiveTooltip();\r\n      }\r\n\r\n      if (isSameTooltipOpen) {\r\n        closeActiveTooltip();\r\n        return;\r\n      }\r\n\r\n      instance.show();\r\n      el.setAttribute(\"aria-expanded\", \"true\");\r\n      activeTrigger = el;\r\n      activeInstance = instance;\r\n    });\r\n  });\r\n\r\n  document.addEventListener(\"click\", (event) => {\r\n    if (!activeTrigger || !activeInstance) return;\r\n\r\n    const target = event.target as Node;\r\n    const activeTooltipEl = document.querySelector(\".tooltip.show\");\r\n\r\n    const clickedTrigger = activeTrigger.contains(target);\r\n    const clickedTooltip = activeTooltipEl?.contains(target) ?? false;\r\n\r\n    if (!clickedTrigger && !clickedTooltip) {\r\n      closeActiveTooltip();\r\n    }\r\n  });\r\n\r\n  document.addEventListener(\"keydown\", (event) => {\r\n    if (event.key === \"Escape\") {\r\n      closeActiveTooltip();\r\n    }\r\n  });\r\n\r\n  document.addEventListener(\"hidden.bs.tooltip\", (event) => {\r\n    const target = event.target as HTMLElement;\r\n\r\n    if (activeTrigger === target) {\r\n      activeTrigger.setAttribute(\"aria-expanded\", \"false\");\r\n      activeTrigger = null;\r\n      activeInstance = null;\r\n    }\r\n  });\r\n};\r\n\r\nexport const initBootstrapToasts = (): void => {\n\n  if (typeof document === \"undefined\") {\n    return;\n  }\n\n  const { Toast } = getBootstrap();\n  if (!Toast) return;\n\n  const toasts = document.querySelectorAll<HTMLElement>(\".toast\");\n\r\n  if (!toasts.length) {\r\n    return;\r\n  }\n\n  toasts.forEach((el) => {\n    if (Toast.getOrCreateInstance) {\n      Toast.getOrCreateInstance(el, {\n        animation: true,\n        autohide: true,\n        delay: 3000,\n      });\n    } else {\n      new Toast(el, {\n        animation: true,\n        autohide: true,\n        delay: 3000,\n      });\n    }\r\n\r\n\r\n  });\r\n};\r\n\r\n\r\nexport const initBootstrapComponents = (): void => {\r\n  initBootstrapCollapse();\r\n  initBootstrapModal();\r\n  initBootstrapTabs();\r\n  initBootstrapTooltips();\r\n  initBootstrapToasts();\r\n};\n","import Toast from \"bootstrap/js/dist/toast\";\n\ntype ToastVariant = \"success\" | \"error\" | \"info\" | \"warning\";\n\ntype AddedToCartButtonLike =\n  | HTMLElement\n  | { get: (index: number) => HTMLElement | undefined }\n  | unknown;\n\ntype JQueryLike = {\n  on: (\n    eventNames: string,\n    handler: (\n      event: Event,\n      fragments?: Record<string, string>,\n      cartHash?: string,\n      button?: AddedToCartButtonLike\n    ) => void\n  ) => void;\n};\n\ntype WooCheckoutErrorResponse = {\n  messages?: string;\n};\n\ntype WindowWithToastHelpers = typeof window & {\n  jQuery?: (selector: HTMLElement | Document | string) => JQueryLike;\n  showToast?: (message: string, variant?: ToastVariant) => void;\n  flushWooCommerceNoticeHtml?: (html: string) => void;\n};\n\nconst TOAST_VARIANT_CLASSES: Record<ToastVariant, string> = {\n  success: \"toast--success\",\n  error: \"toast--error\",\n  info: \"toast--info\",\n  warning: \"toast--warning\",\n};\n\nconst MAX_VISIBLE_TOASTS = 4;\nconst EARLY_DISMISS_DELAY_MS = 900;\nconst EARLY_DISMISS_STAGGER_MS = 120;\n\nconst pendingToasts: { message: string; variant: ToastVariant }[] = [];\n\nconst getButtonElement = (button?: AddedToCartButtonLike): HTMLElement | null => {\n  if (!button) return null;\n\n  if (button instanceof HTMLElement) {\n    return button;\n  }\n\n  if (\n    typeof button === \"object\" &&\n    button !== null &&\n    \"get\" in button &&\n    typeof (button as { get: unknown }).get === \"function\"\n  ) {\n    return (button as { get: (index: number) => HTMLElement | undefined }).get(0) ?? null;\n  }\n\n  return null;\n};\n\nconst cleanText = (value: string): string =>\n  value.replace(/\\u00A0/g, \" \").replace(/\\s+/g, \" \").trim();\n\nconst cleanProductName = (value: string): string =>\n  cleanText(value).replace(/^\\s*(dodaj do koszyka|do koszyka)\\s*:?\\s*/i, \"\");\n\nconst getProductNameFromContext = (buttonEl: HTMLElement | null): string | null => {\n  if (!buttonEl) return null;\n\n  const productCardTitle = buttonEl\n    .closest(\".c-product-card\")\n    ?.querySelector<HTMLElement>(\".c-product-card__title, h2, h3\");\n\n  if (productCardTitle?.textContent?.trim()) {\n    return cleanProductName(productCardTitle.textContent);\n  }\n\n  if (buttonEl.matches(\".single_add_to_cart_button\")) {\n    const singleProductTitle = document.querySelector<HTMLElement>(\".product_title, .entry-title\");\n\n    if (singleProductTitle?.textContent?.trim()) {\n      return cleanProductName(singleProductTitle.textContent);\n    }\n  }\n\n  return null;\n};\n\nconst getProductNameFromButton = (buttonEl: HTMLElement | null): string => {\n  const contextualName = getProductNameFromContext(buttonEl);\n\n  if (contextualName) {\n    return contextualName;\n  }\n\n  const rawName =\n    buttonEl?.getAttribute(\"data-product_name\") ||\n    buttonEl?.getAttribute(\"aria-label\") ||\n    buttonEl?.textContent?.trim() ||\n    \"Produkt\";\n\n  return cleanProductName(rawName) || \"Produkt\";\n};\n\nconst getPolishQuantityLabel = (quantity: number): string => {\n  if (quantity === 1) return \"1 sztuka\";\n\n  const mod10 = quantity % 10;\n  const mod100 = quantity % 100;\n\n  if (mod10 >= 2 && mod10 <= 4 && !(mod100 >= 12 && mod100 <= 14)) {\n    return `${quantity} sztuki`;\n  }\n\n  return `${quantity} sztuk`;\n};\n\nconst mapNoticeTypeToToastVariant = (type?: string): ToastVariant => {\n  switch (type) {\n    case \"success\":\n      return \"success\";\n    case \"error\":\n      return \"error\";\n    case \"warning\":\n      return \"warning\";\n    case \"notice\":\n    case \"info\":\n    default:\n      return \"info\";\n  }\n};\n\nconst getToastContainer = (): HTMLElement | null =>\n  document.getElementById(\"cartToastContainer\");\n\nconst getToastTemplate = (): HTMLTemplateElement | null => {\n  const template = document.getElementById(\"cartToastTemplate\");\n  return template instanceof HTMLTemplateElement ? template : null;\n};\n\nconst normalizeToastMessage = (message: string): string => {\n  const wrapper = document.createElement(\"div\");\n  wrapper.innerHTML = message;\n\n  wrapper\n    .querySelectorAll(\".restore-item, a[href*='undo_item'], a[href*='undo']\")\n    .forEach((restoreLink) => restoreLink.remove());\n\n  return cleanText(wrapper.textContent || wrapper.innerText || message);\n};\n\nconst getToastDelay = (message: string, variant: ToastVariant): number => {\n  const words = normalizeToastMessage(message).split(/\\s+/).filter(Boolean).length;\n  const readingTimeMs = Math.ceil((words / 3) * 1000);\n  const minDelayMs = variant === \"error\" || variant === \"warning\" ? 5500 : 4000;\n  const extraBufferMs = variant === \"error\" || variant === \"warning\" ? 3500 : 2500;\n\n  return Math.min(8000, Math.max(minDelayMs, readingTimeMs + extraBufferMs));\n};\n\nconst getActiveToastElements = (container: HTMLElement): HTMLElement[] =>\n  Array.from(container.querySelectorAll<HTMLElement>(\".toast\"));\n\nconst syncToastBackgroundState = (): void => {\n  const container = getToastContainer();\n  const background = document.querySelector<HTMLElement>(\".js-toast-bg\");\n\n  if (!container || !background) return;\n\n  background.classList.toggle(\"--active\", getActiveToastElements(container).length > 0);\n};\n\nconst setToastA11yAttributes = (toastEl: HTMLElement, variant: ToastVariant): void => {\n  toastEl.setAttribute(\"role\", variant === \"error\" ? \"alert\" : \"status\");\n  toastEl.setAttribute(\"aria-live\", variant === \"error\" ? \"assertive\" : \"polite\");\n  toastEl.setAttribute(\"aria-atomic\", \"true\");\n};\n\nconst scheduleToastHideSoon = (toastEl: HTMLElement, index: number): void => {\n  if (toastEl.dataset.toastClosingSoon === \"true\") return;\n\n  toastEl.dataset.toastClosingSoon = \"true\";\n\n  window.setTimeout(() => {\n    Toast.getOrCreateInstance(toastEl).hide();\n  }, EARLY_DISMISS_DELAY_MS + index * EARLY_DISMISS_STAGGER_MS);\n};\n\nconst requestToastSlots = (): void => {\n  const container = getToastContainer();\n  if (!container) return;\n\n  const activeToasts = getActiveToastElements(container);\n  const overflow = activeToasts.length + pendingToasts.length - MAX_VISIBLE_TOASTS;\n\n  if (overflow <= 0) return;\n\n  let scheduled = 0;\n\n  for (const toastEl of activeToasts) {\n    if (scheduled >= overflow) break;\n    if (toastEl.dataset.toastClosingSoon === \"true\") continue;\n\n    scheduleToastHideSoon(toastEl, scheduled);\n    scheduled += 1;\n  }\n};\n\nconst drainPendingToasts = (): void => {\n  const container = getToastContainer();\n  const template = getToastTemplate();\n\n  if (!container || !template) return;\n\n  while (pendingToasts.length > 0 && getActiveToastElements(container).length < MAX_VISIBLE_TOASTS) {\n    const nextToast = pendingToasts.shift();\n    if (!nextToast) break;\n\n    renderToast(nextToast.message, nextToast.variant, container, template);\n  }\n\n  syncToastBackgroundState();\n};\n\nconst renderToast = (\n  message: string,\n  variant: ToastVariant,\n  container: HTMLElement,\n  template: HTMLTemplateElement\n): void => {\n  const normalizedMessage = normalizeToastMessage(message);\n\n  if (!normalizedMessage) return;\n\n  const fragment = template.content.cloneNode(true) as DocumentFragment;\n  const toastEl = fragment.querySelector<HTMLElement>(\".toast\");\n  const textEl = fragment.querySelector<HTMLElement>(\".js-cart-toast-text\");\n\n  if (!toastEl || !textEl) return;\n\n  textEl.textContent = normalizedMessage;\n  toastEl.classList.remove(...Object.values(TOAST_VARIANT_CLASSES));\n  toastEl.classList.add(TOAST_VARIANT_CLASSES[variant]);\n  setToastA11yAttributes(toastEl, variant);\n\n  const delay = getToastDelay(normalizedMessage, variant);\n  toastEl.setAttribute(\"data-bs-delay\", String(delay));\n\n  container.appendChild(toastEl);\n  syncToastBackgroundState();\n\n  const toast = Toast.getOrCreateInstance(toastEl, {\n    animation: true,\n    autohide: true,\n    delay,\n  });\n\n  toastEl.addEventListener(\"hidden.bs.toast\", () => {\n    toastEl.remove();\n    syncToastBackgroundState();\n    drainPendingToasts();\n    requestToastSlots();\n  });\n\n  toast.show();\n};\n\nconst showToast = (message: string, variant: ToastVariant = \"success\"): void => {\n  const container = getToastContainer();\n  const template = getToastTemplate();\n\n  if (!container || !template) return;\n\n  if (getActiveToastElements(container).length >= MAX_VISIBLE_TOASTS) {\n    pendingToasts.push({ message, variant });\n    requestToastSlots();\n    return;\n  }\n\n  renderToast(message, variant, container, template);\n  requestToastSlots();\n};\n\nconst flushWooCommerceNotices = (scope: ParentNode = document): void => {\n  const notices = scope.querySelectorAll<HTMLElement>(\".js-wc-toast-notice\");\n\n  notices.forEach((noticeEl) => {\n    if (noticeEl.dataset.toastRendered === \"true\") return;\n\n    showToast(noticeEl.innerHTML, mapNoticeTypeToToastVariant(noticeEl.dataset.toastType));\n    noticeEl.dataset.toastRendered = \"true\";\n    noticeEl.remove();\n  });\n};\n\nconst flushWooCommerceNoticeHtml = (html: string): void => {\n  if (!html) return;\n\n  const wrapper = document.createElement(\"div\");\n  wrapper.innerHTML = html;\n  flushWooCommerceNotices(wrapper);\n};\n\nconst bindWooCommerceJQueryEvents = (): void => {\n  const win = window as WindowWithToastHelpers;\n\n  if (typeof win.jQuery !== \"function\") return;\n\n  win.jQuery(document.body).on(\n    \"added_to_cart\",\n    (\n      _event: Event,\n      _fragments?: Record<string, string>,\n      _cartHash?: string,\n      button?: AddedToCartButtonLike\n    ): void => {\n      const productName = getProductNameFromButton(getButtonElement(button));\n\n      window.setTimeout(() => {\n        showToast(`Dodano do koszyka: ${productName}`, \"success\");\n      }, 50);\n    }\n  );\n\n  win.jQuery(document.body).on(\n    \"updated_wc_div updated_cart_totals updated_checkout applied_coupon removed_coupon wc_fragments_loaded cart_page_refreshed cart_totals_refreshed\",\n    (): void => {\n      window.setTimeout(() => flushWooCommerceNotices(), 50);\n    }\n  );\n\n  win.jQuery(document.body).on(\n    \"checkout_error\",\n    (_event: Event, response?: WooCheckoutErrorResponse): void => {\n      window.setTimeout(() => {\n        if (response?.messages) {\n          flushWooCommerceNoticeHtml(response.messages);\n          return;\n        }\n\n        flushWooCommerceNotices();\n      }, 50);\n    }\n  );\n};\n\nconst bindCustomWindowEvents = (): void => {\n  window.addEventListener(\n    \"cart_item_added\",\n    ((event: Event) => {\n      const custom = event as CustomEvent<{ button?: AddedToCartButtonLike }>;\n      const productName = getProductNameFromButton(getButtonElement(custom.detail?.button));\n      showToast(`Dodano do koszyka: ${productName}`, \"success\");\n    }) as EventListener\n  );\n\n  window.addEventListener(\n    \"cart_item_removed\",\n    ((event: Event) => {\n      const custom = event as CustomEvent<{ productName: string; quantity: number }>;\n      const { productName, quantity } = custom.detail;\n      showToast(`Usunięto z koszyka: ${productName} (${getPolishQuantityLabel(quantity)})`, \"info\");\n    }) as EventListener\n  );\n\n  window.addEventListener(\n    \"cart_item_updated\",\n    ((event: Event) => {\n      const custom = event as CustomEvent<{ productName: string; quantity: number }>;\n      const { productName, quantity } = custom.detail;\n      showToast(\n        `Zaktualizowano koszyk: ${productName} (${getPolishQuantityLabel(quantity)})`,\n        \"info\"\n      );\n    }) as EventListener\n  );\n\n  window.addEventListener(\n    \"cart_coupon_applied\",\n    ((event: Event) => {\n      const custom = event as CustomEvent<{ message?: string }>;\n      showToast(custom.detail?.message || \"Kod rabatowy został aktywowany.\", \"success\");\n    }) as EventListener\n  );\n\n  window.addEventListener(\n    \"cart_coupon_removed\",\n    ((event: Event) => {\n      const custom = event as CustomEvent<{ message?: string }>;\n      showToast(custom.detail?.message || \"Kupon został usunięty.\", \"info\");\n    }) as EventListener\n  );\n\n  window.addEventListener(\n    \"cart_coupon_error\",\n    ((event: Event) => {\n      const custom = event as CustomEvent<{ message?: string }>;\n      showToast(custom.detail?.message || \"Nie udało się wykonać operacji na kuponie.\", \"error\");\n    }) as EventListener\n  );\n\n  window.addEventListener(\n    \"cart_coupon_auto_removed\",\n    ((event: Event) => {\n      const custom = event as CustomEvent<{ message?: string }>;\n      showToast(\n        custom.detail?.message ||\n          \"Jeden z kuponów punktowych został automatycznie usunięty po zmianie koszyka.\",\n        \"warning\"\n      );\n    }) as EventListener\n  );\n\n  window.addEventListener(\n    \"cart_notice\",\n    ((event: Event) => {\n      const custom = event as CustomEvent<{ message?: string; type?: string }>;\n\n      if (!custom.detail?.message) {\n        return;\n      }\n\n      showToast(custom.detail.message, mapNoticeTypeToToastVariant(custom.detail.type));\n    }) as EventListener\n  );\n};\n\nexport const initToast = (): void => {\n  if (document.body.dataset.cartToastInitialized === \"true\") return;\n\n  document.body.dataset.cartToastInitialized = \"true\";\n\n  syncToastBackgroundState();\n  flushWooCommerceNotices();\n  bindWooCommerceJQueryEvents();\n  bindCustomWindowEvents();\n\n  const win = window as WindowWithToastHelpers;\n  win.showToast = showToast;\n  win.flushWooCommerceNoticeHtml = flushWooCommerceNoticeHtml;\n};\n","export const initProductBottomBar = (): void => {\n  if (typeof window === \"undefined\" || typeof document === \"undefined\") return;\n\n  let ticking = false;\n  let archiveModeInitialized = false;\n\n  const getBar = (): HTMLElement | null =>\n    document.querySelector<HTMLElement>(\"[data-product-bottom-bar]\");\n\n  const setVisible = (isVisible: boolean): void => {\n    const bar = getBar();\n    if (!bar) return;\n\n    bar.classList.toggle(\"--visible\", isVisible);\n    bar.setAttribute(\"aria-hidden\", String(!isVisible));\n  };\n\n  const getArchiveQuantityInputs = (): HTMLInputElement[] =>\n    Array.from(document.querySelectorAll<HTMLInputElement>(\"[data-archive-group-quantity]\"));\n\n  const getQuantityValue = (input: HTMLInputElement): number => {\n    const value = Number.parseInt(input.value.replace(/[^\\d]/g, \"\"), 10);\n    return Number.isFinite(value) && value > 0 ? value : 0;\n  };\n\n  const formatPrice = (value: number, currency: string): string =>\n    new Intl.NumberFormat(document.documentElement.lang || \"pl-PL\", {\n      style: \"currency\",\n      currency,\n    }).format(value);\n\n  const setButtonDisabled = (button: HTMLButtonElement, isDisabled: boolean): void => {\n    button.disabled = isDisabled;\n    button.setAttribute(\"aria-disabled\", String(isDisabled));\n    button.classList.toggle(\"disabled\", isDisabled);\n  };\n\n  const updateArchiveGroupButtons = (): void => {\n    document.querySelectorAll<HTMLFormElement>(\"[data-archive-precart-form]\").forEach((form) => {\n      const totalQuantity = Array.from(\n        form.querySelectorAll<HTMLInputElement>(\"[data-archive-group-quantity]\")\n      ).reduce((sum, input) => sum + getQuantityValue(input), 0);\n      const button = form.querySelector<HTMLButtonElement>(\"[data-archive-group-submit]\");\n\n      if (button) setButtonDisabled(button, totalQuantity <= 0);\n    });\n  };\n\n  const updateArchivePreCart = (): void => {\n    const inputs = getArchiveQuantityInputs();\n    const bar = getBar();\n\n    if (!bar || inputs.length === 0) return;\n\n    const currency = bar.dataset.currencyCode || \"PLN\";\n    const totals = inputs.reduce(\n      (result, input) => {\n        const quantity = getQuantityValue(input);\n        const price = Number.parseFloat(input.dataset.productPrice || \"0\");\n\n        result.quantity += quantity;\n        result.total += quantity * (Number.isFinite(price) ? price : 0);\n\n        return result;\n      },\n      { quantity: 0, total: 0 }\n    );\n\n    const countEl = bar.querySelector<HTMLElement>(\".js-product-bottom-bar-count\");\n    const totalEl = bar.querySelector<HTMLElement>(\".js-product-bottom-bar-total\");\n    const submitEl = bar.querySelector<HTMLElement>(\"[data-product-bottom-bar-submit]\");\n    const labelEl = submitEl?.querySelector<HTMLElement>(\"span\");\n\n    bar.dataset.itemsCount = String(totals.quantity);\n    if (countEl) countEl.textContent = String(totals.quantity);\n    if (totalEl) totalEl.textContent = formatPrice(totals.total, currency);\n    if (labelEl) labelEl.textContent = \"Dodaj wszystko do koszyka\";\n    submitEl?.classList.toggle(\"disabled\", totals.quantity <= 0);\n    submitEl?.setAttribute(\"aria-disabled\", String(totals.quantity <= 0));\n\n    updateArchiveGroupButtons();\n  };\n\n  const submitArchivePreCart = (): void => {\n    const selectedInputs = getArchiveQuantityInputs().filter((input) => getQuantityValue(input) > 0);\n    const sourceForm = selectedInputs[0]?.closest<HTMLFormElement>(\"form\");\n\n    if (!sourceForm) return;\n\n    const form = document.createElement(\"form\");\n    form.method = \"post\";\n    form.action = sourceForm.action || window.location.href;\n    form.style.display = \"none\";\n\n    const appendHidden = (name: string, value: string): void => {\n      const input = document.createElement(\"input\");\n      input.type = \"hidden\";\n      input.name = name;\n      input.value = value;\n      form.appendChild(input);\n    };\n\n    const nonce = sourceForm.querySelector<HTMLInputElement>(\n      'input[name=\"healion_archive_group_add_to_cart_nonce\"]'\n    )?.value;\n\n    appendHidden(\"healion_archive_group_add_to_cart\", \"1\");\n    if (nonce) appendHidden(\"healion_archive_group_add_to_cart_nonce\", nonce);\n\n    selectedInputs.forEach((input) => {\n      const productId = input.dataset.productId;\n      if (!productId) return;\n\n      appendHidden(`healion_archive_group_quantities[${productId}]`, String(getQuantityValue(input)));\n    });\n\n    document.body.appendChild(form);\n    form.submit();\n  };\n\n  const update = (): void => {\n    const bar = getBar();\n\n    if (!bar) {\n      ticking = false;\n      return;\n    }\n\n    updateArchivePreCart();\n\n    const itemsCount = Number(bar.dataset.itemsCount ?? \"0\");\n\n    if (itemsCount <= 0) {\n      bar.classList.add(\"d-none\");\n      bar.classList.remove(\"--visible\", \"--stopped\");\n      bar.style.removeProperty(\"--product-bottom-bar-top\");\n      bar.setAttribute(\"aria-hidden\", \"true\");\n      ticking = false;\n      return;\n    }\n\n    if (getArchiveQuantityInputs().length > 0) {\n      bar.classList.remove(\"d-none\", \"--stopped\");\n      bar.style.removeProperty(\"--product-bottom-bar-top\");\n      setVisible(true);\n      ticking = false;\n      return;\n    }\n\n    bar.classList.remove(\"d-none\");\n\n    const header = document.querySelector<HTMLElement>(\".headerWrapper\");\n    const footer = document.querySelector<HTMLElement>(\".c-footer\");\n    const isHeaderGone = header\n      ? header.getBoundingClientRect().bottom <= 0\n      : window.scrollY > 160;\n\n    const shouldStopAtFooter = footer\n      ? footer.getBoundingClientRect().top <= window.innerHeight\n      : false;\n\n    if (footer && shouldStopAtFooter) {\n      const footerTop = footer.getBoundingClientRect().top + window.scrollY;\n      const barTop = Math.max(0, footerTop - bar.offsetHeight);\n\n      bar.style.setProperty(\"--product-bottom-bar-top\", `${barTop}px`);\n      bar.classList.add(\"--stopped\");\n    } else {\n      bar.classList.remove(\"--stopped\");\n      bar.style.removeProperty(\"--product-bottom-bar-top\");\n    }\n\n    setVisible(isHeaderGone);\n    ticking = false;\n  };\n\n  const requestUpdate = (): void => {\n    if (ticking) return;\n    ticking = true;\n    window.requestAnimationFrame(update);\n  };\n\n  update();\n\n  if (document.body.dataset.productBottomBarBound === \"true\") {\n    requestUpdate();\n    return;\n  }\n\n  document.body.dataset.productBottomBarBound = \"true\";\n  window.addEventListener(\"scroll\", requestUpdate, { passive: true });\n  window.addEventListener(\"resize\", requestUpdate);\n  document.addEventListener(\"input\", (event) => {\n    if (!(event.target instanceof HTMLInputElement)) return;\n    if (!event.target.matches(\"[data-archive-group-quantity]\")) return;\n\n    requestUpdate();\n  });\n  document.addEventListener(\"click\", (event) => {\n    const target = event.target;\n\n    if (!(target instanceof Element)) return;\n    if (!target.closest(\"[data-product-bottom-bar-submit]\")) return;\n    if (getArchiveQuantityInputs().length === 0) return;\n\n    event.preventDefault();\n    if (Number(getBar()?.dataset.itemsCount ?? \"0\") <= 0) return;\n\n    submitArchivePreCart();\n  });\n  document.addEventListener(\"submit\", (event) => {\n    const form = event.target;\n\n    if (!(form instanceof HTMLFormElement)) return;\n    if (!form.matches(\"[data-archive-precart-form]\")) return;\n\n    const totalQuantity = Array.from(\n      form.querySelectorAll<HTMLInputElement>(\"[data-archive-group-quantity]\")\n    ).reduce((sum, input) => sum + getQuantityValue(input), 0);\n\n    if (totalQuantity <= 0) event.preventDefault();\n  });\n\n  if (!archiveModeInitialized && getArchiveQuantityInputs().length > 0) {\n    archiveModeInitialized = true;\n    requestUpdate();\n  }\n\n  const win = window as typeof window & {\n    jQuery?: (selector: HTMLElement | Document | Window | string) => {\n      on: (events: string, handler: () => void) => void;\n    };\n  };\n\n  if (typeof win.jQuery === \"function\") {\n    win.jQuery(document.body).on(\n      \"added_to_cart removed_from_cart updated_wc_div wc_fragments_loaded wc_fragments_refreshed\",\n      () => {\n        window.setTimeout(requestUpdate, 50);\n      }\n    );\n    win.jQuery(window).on(\n      \"wcpf_before_ajax_filtering wcpf_update_products wcpf_after_ajax_filtering\",\n      () => {\n        window.setTimeout(requestUpdate, 50);\n      }\n    );\n  }\n};\n","const getDrawerElements = () => {\n  const drawer = document.querySelector<HTMLElement>(\".c-cart-drawer\");\n  const toggles = document.querySelectorAll<HTMLElement>(\".cart-toggle\");\n\n  return {\n    drawer,\n    toggles,\n  };\n};\n\nconst closeMobileMenu = (): void => {\n  const mobileMenu = document.querySelector<HTMLElement>(\".headerMenu.--showMobile\");\n  const hamburger = document.querySelector<HTMLElement>(\".headerMainHamburger .c-btn\");\n  const primaryHeader = document.querySelector<HTMLElement>(\".primaryHeader\");\n\n  mobileMenu?.classList.remove(\"--showMobile\");\n  mobileMenu?.setAttribute(\"aria-hidden\", \"true\");\n  hamburger?.setAttribute(\"aria-expanded\", \"false\");\n  primaryHeader?.classList.remove(\"--openMenu\");\n};\n\nexport const openCartDrawer = (): void => {\n  const { drawer, toggles } = getDrawerElements();\n  if (!drawer) return;\n\n  closeMobileMenu();\n  drawer.classList.add(\"--show\");\n  drawer.setAttribute(\"aria-hidden\", \"false\");\n  document.body.classList.add(\"cart-drawer-open\");\n\n  toggles.forEach((toggle) => {\n    toggle.setAttribute(\"aria-expanded\", \"true\");\n  });\n};\n\nexport const closeCartDrawer = (): void => {\n  const { drawer, toggles } = getDrawerElements();\n  if (!drawer) return;\n\n  drawer.classList.remove(\"--show\");\n  drawer.setAttribute(\"aria-hidden\", \"true\");\n  document.body.classList.remove(\"cart-drawer-open\");\n\n  toggles.forEach((toggle) => {\n    toggle.setAttribute(\"aria-expanded\", \"false\");\n  });\n};\n\nexport const initCartDrawer = (): void => {\n  const { drawer } = getDrawerElements();\n\n  if (drawer && drawer.dataset.cartDrawerBackdropBound !== \"true\") {\n    drawer.addEventListener(\"click\", (event) => {\n      if (event.target === drawer) {\n        closeCartDrawer();\n      }\n    });\n\n    drawer.dataset.cartDrawerBackdropBound = \"true\";\n  }\n\n  if (document.body.dataset.cartDrawerDelegatedBound !== \"true\") {\n    document.addEventListener(\"click\", (event) => {\n      const target = event.target as Element | null;\n      const toggle = target?.closest<HTMLElement>(\".cart-toggle\");\n      const closeButton = target?.closest<HTMLElement>(\".cart-close\");\n\n      if (!toggle && !closeButton) return;\n\n      event.preventDefault();\n\n      if (closeButton) {\n        closeCartDrawer();\n        return;\n      }\n\n      const currentDrawer = document.querySelector<HTMLElement>(\".c-cart-drawer\");\n      if (!currentDrawer) return;\n\n      if (currentDrawer.classList.contains(\"--show\")) {\n        closeCartDrawer();\n        return;\n      }\n\n      openCartDrawer();\n    });\n\n    document.body.dataset.cartDrawerDelegatedBound = \"true\";\n  }\n\n  if (document.body.dataset.cartDrawerEscBound !== \"true\") {\n    document.addEventListener(\"keydown\", (event) => {\n      const currentDrawer = document.querySelector<HTMLElement>(\".c-cart-drawer\");\n\n      if (event.key === \"Escape\" && currentDrawer?.classList.contains(\"--show\")) {\n        closeCartDrawer();\n      }\n    });\n\n    document.body.dataset.cartDrawerEscBound = \"true\";\n  }\n};\n","import { getBootstrap } from \"./bootstrap\";\n\nconst DESKTOP_BREAKPOINT = \"(min-width: 992px)\";\nconst EAN_FILTER_KEYS = [\"ean13\", \"ean\"];\nconst EAN_FILTER_GROUP_KEY = \"inkospornova-ean13\";\n\ntype JQueryInstance = {\n  data: (key: string, value?: unknown) => unknown;\n  on: (events: string, handler: (...args: unknown[]) => void) => void;\n  hasClass?: (className: string) => boolean;\n};\n\ntype JQueryLike = {\n  (selector: Element | Window | Document | string): JQueryInstance;\n  fn?: {\n    data?: (key?: string | Record<string, unknown>, value?: unknown) => unknown;\n  };\n};\n\nconst moveFiltersContent = (\n  contentEl: HTMLElement,\n  targetEl: HTMLElement\n): void => {\n  if (contentEl.parentElement === targetEl) {\n    return;\n  }\n\n  targetEl.appendChild(contentEl);\n};\n\nconst hideOffcanvas = (offcanvasEl: HTMLElement): void => {\n  const { Offcanvas } = getBootstrap() as {\n    Offcanvas?: {\n      getInstance?: (el: Element) => { hide: () => void } | null;\n      getOrCreateInstance?: (el: Element) => { hide: () => void };\n    };\n  };\n\n  if (!Offcanvas) {\n    return;\n  }\n\n  const instance =\n    Offcanvas.getInstance?.(offcanvasEl) ??\n    Offcanvas.getOrCreateInstance?.(offcanvasEl);\n\n  instance?.hide();\n};\n\nconst purgeStaleWcpfNotes = (): void => {\n  const win = window as typeof window & {\n    jQuery?: JQueryLike;\n  };\n\n  if (typeof win.jQuery !== \"function\") {\n    return;\n  }\n\n  document.querySelectorAll<HTMLElement>(\".c-wcpf-note-item\").forEach((noteEl) => {\n    const entry = win.jQuery?.(noteEl).data(\"wcpf-note-entry\");\n\n    if (!entry || typeof entry !== \"object\" || !(\"filterComponent\" in entry)) {\n      win.jQuery?.(noteEl).data(\"wcpf-note-entry\", {\n        filterComponent: {\n          entity: {\n            entityId: \"__inkospornova_missing_wcpf_note__\",\n          },\n        },\n      });\n    }\n  });\n};\n\nconst getUrl = (): URL | null => {\n  try {\n    return new URL(window.location.href);\n  } catch {\n    return null;\n  }\n};\n\nconst getActiveEanFilter = (): string => {\n  const url = getUrl();\n\n  if (!url) {\n    return \"\";\n  }\n\n  for (const key of EAN_FILTER_KEYS) {\n    const value = url.searchParams.get(key)?.trim();\n\n    if (value) {\n      return value;\n    }\n  }\n\n  return \"\";\n};\n\nconst getProductFilterId = (): string => {\n  const notes = document.querySelector<HTMLElement>(\".wcpf-filter-notes\");\n  const notesClass = Array.from(notes?.classList ?? []).find((className) =>\n    className.startsWith(\"wcpf-filter-notes-\")\n  );\n\n  if (notesClass) {\n    return notesClass.replace(\"wcpf-filter-notes-\", \"\");\n  }\n\n  const container = document.querySelector<HTMLElement>(\n    \"[class*='wcpf-products-container-']\"\n  );\n  const containerClass = Array.from(container?.classList ?? []).find((className) =>\n    className.startsWith(\"wcpf-products-container-\")\n  );\n\n  return containerClass?.replace(\"wcpf-products-container-\", \"\") || \"56\";\n};\n\nconst removeEanFromCurrentUrl = (): string | null => {\n  const url = getUrl();\n\n  if (!url) {\n    return null;\n  }\n\n  EAN_FILTER_KEYS.forEach((key) => url.searchParams.delete(key));\n  url.searchParams.delete(\"paged\");\n  url.searchParams.delete(\"product-page\");\n\n  return url.toString();\n};\n\nconst hasNonEanFilterNotes = (): boolean =>\n  Array.from(document.querySelectorAll<HTMLElement>(\".c-wcpf-note-item\")).some(\n    (noteEl) => noteEl.dataset.eanFilterNote !== \"true\"\n  );\n\nconst getOrCreateFilterNotes = (): HTMLElement | null => {\n  let notes = document.querySelector<HTMLElement>(\".wcpf-filter-notes\");\n\n  if (notes) {\n    return notes;\n  }\n\n  const listing = document.querySelector<HTMLElement>(\".c-product-section\");\n\n  if (!listing?.parentElement) {\n    return null;\n  }\n\n  const wrapper = document.createElement(\"div\");\n  wrapper.className =\n    \"c-product-listing__wcpf-note d-flex flex-column gap-16 mb-24\";\n  wrapper.dataset.eanFilterNotesWrapper = \"true\";\n  wrapper.innerHTML = `\n    <div class=\"d-flex flex-wrap gap-8\">\n      <div class=\"wcpf-filter-notes d-flex gap-8 w-100 align-items-start justify-content-between no-wrap wcpf-filter-notes-${getProductFilterId()}\">\n        <div class=\"wcpf-note-list d-flex flex-wrap r-gap-8\"></div>\n      </div>\n    </div>\n  `;\n\n  listing.parentElement.insertBefore(wrapper, listing);\n  notes = wrapper.querySelector<HTMLElement>(\".wcpf-filter-notes\");\n\n  return notes;\n};\n\nconst removeEmptyEanNotesWrapper = (): void => {\n  const wrapper = document.querySelector<HTMLElement>(\n    \"[data-ean-filter-notes-wrapper='true']\"\n  );\n\n  if (\n    wrapper &&\n    !wrapper.querySelector(\".c-wcpf-note-item\") &&\n    !wrapper.querySelector(\".js-wcpf-clear-all\")\n  ) {\n    wrapper.remove();\n  }\n};\n\nconst ensureEanClearAllButton = (notes: HTMLElement): void => {\n  if (notes.querySelector(\".js-wcpf-clear-all\")) {\n    return;\n  }\n\n  const button = document.createElement(\"button\");\n  button.type = \"button\";\n  button.className = \"c-btn c-btn-s c-btn-text chip-s js-wcpf-clear-all\";\n  button.innerHTML = `\n    <span class=\"c-product-left-side__clear fw-bold text-nowrap\">Wyczyść filtry</span>\n    <svg width=\"16\" height=\"16\" viewBox=\"0 0 16 16\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" aria-hidden=\"true\" focusable=\"false\">\n      <path fill-rule=\"evenodd\" clip-rule=\"evenodd\" d=\"M5.792 1.417v1h4.125v-1H5.792Zm5.625 1V1.292c0-.365-.145-.714-.403-.972A1.375 1.375 0 0 0 10.042-.083H5.667c-.365 0-.714.145-.972.403a1.375 1.375 0 0 0-.403.972v1.125H.667a.75.75 0 0 0 0 1.5h.887l1.061 10.084c.052.491.284.946.651 1.277.367.331.844.514 1.338.514h6.5c.494 0 .971-.183 1.338-.514.367-.331.599-.786.651-1.277l1.062-10.084h.887a.75.75 0 0 0 0-1.5h-3.625Zm-.75 1.5H3.063l1.044 9.927c.013.123.071.237.163.319.092.083.211.129.335.129h6.499a.5.5 0 0 0 .497-.448l1.045-9.927h-1.979Z\" fill=\"#030507\"/>\n    </svg>\n  `;\n\n  notes.appendChild(button);\n};\n\nconst renderEanFilterNote = (): void => {\n  const activeEan = getActiveEanFilter();\n  const existingGroup = document.querySelector<HTMLElement>(\n    `[data-group-key=\"${EAN_FILTER_GROUP_KEY}\"]`\n  );\n\n  if (!activeEan) {\n    existingGroup?.remove();\n    removeEmptyEanNotesWrapper();\n    return;\n  }\n\n  const notes = getOrCreateFilterNotes();\n  const notesList = notes?.querySelector<HTMLElement>(\".wcpf-note-list\");\n\n  if (!notes || !notesList) {\n    return;\n  }\n\n  let group = existingGroup;\n\n  if (!group) {\n    group = document.createElement(\"div\");\n    group.className =\n      \"wcpf-note-list-group d-flex align-items-start mr-8\";\n    group.dataset.groupKey = EAN_FILTER_GROUP_KEY;\n    group.innerHTML = `\n      <span class=\"chip chip-s chip-s-name fw-bolder A\">PRODUKT (EAN13)</span>\n      <div class=\"wcpf-note-list-items d-flex flex-wrap gap-8\"></div>\n    `;\n    notesList.appendChild(group);\n  }\n\n  const items = group.querySelector<HTMLElement>(\".wcpf-note-list-items\");\n\n  if (!items) {\n    return;\n  }\n\n  items.innerHTML = `\n    <div class=\"c-wcpf-note-item chip chip-s --active js-ean13-filter-note\" data-ean-filter-note=\"true\">\n      <span>${activeEan}</span>\n      <svg class=\"js-remove-filter js-ean13-filter-remove\" width=\"16\" height=\"16\" viewBox=\"0 0 16 16\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" aria-hidden=\"true\" focusable=\"false\">\n        <path fill-rule=\"evenodd\" clip-rule=\"evenodd\" d=\"M2.137 2.136a.75.75 0 0 1 1.06 0L8 6.94l4.803-4.803a.75.75 0 1 1 1.061 1.061L9.061 8l4.803 4.803a.75.75 0 0 1-1.061 1.061L8 9.061l-4.803 4.803a.75.75 0 0 1-1.06-1.061L6.938 8 2.137 3.197a.75.75 0 0 1 0-1.061Z\" fill=\"black\"/>\n      </svg>\n    </div>\n  `;\n\n  ensureEanClearAllButton(notes);\n};\n\nconst syncEanHiddenInputs = (): void => {\n  const activeEan = getActiveEanFilter();\n\n  document.querySelectorAll<HTMLFormElement>(\"form.woocommerce-ordering\").forEach(\n    (form) => {\n      let input = form.querySelector<HTMLInputElement>('input[name=\"ean13\"]');\n\n      if (!activeEan) {\n        input?.remove();\n        return;\n      }\n\n      if (!input) {\n        input = document.createElement(\"input\");\n        input.type = \"hidden\";\n        input.name = \"ean13\";\n        form.appendChild(input);\n      }\n\n      input.value = activeEan;\n    }\n  );\n};\n\nconst navigateWithoutEanFilter = (): void => {\n  const cleanUrl = removeEanFromCurrentUrl();\n\n  if (!cleanUrl) {\n    return;\n  }\n\n  window.location.assign(cleanUrl);\n};\n\nconst initEanFilterIntegration = (): void => {\n  if (document.body.dataset.eanFilterIntegrationInitialized === \"true\") {\n    renderEanFilterNote();\n    syncEanHiddenInputs();\n    return;\n  }\n\n  document.body.dataset.eanFilterIntegrationInitialized = \"true\";\n\n  document.addEventListener(\n    \"click\",\n    (event) => {\n      const target = event.target;\n\n      if (!(target instanceof Element)) {\n        return;\n      }\n\n      if (target.closest(\".js-ean13-filter-note, .js-ean13-filter-remove\")) {\n        event.preventDefault();\n        event.stopImmediatePropagation();\n        navigateWithoutEanFilter();\n        return;\n      }\n\n      if (target.closest(\".js-wcpf-clear-all\") && getActiveEanFilter()) {\n        const cleanUrl = removeEanFromCurrentUrl();\n\n        if (!cleanUrl) {\n          return;\n        }\n\n        if (!hasNonEanFilterNotes()) {\n          event.preventDefault();\n          event.stopImmediatePropagation();\n          window.location.assign(cleanUrl);\n          return;\n        }\n\n        window.history.replaceState({}, document.title, cleanUrl);\n      }\n    },\n    true\n  );\n\n  const win = window as typeof window & {\n    jQuery?: JQueryLike;\n  };\n\n  if (typeof win.jQuery === \"function\") {\n    win.jQuery(window).on(\n      \"wcpf_before_ajax_filtering wcpf_update_products wcpf_after_ajax_filtering\",\n      () => {\n        renderEanFilterNote();\n        syncEanHiddenInputs();\n      }\n    );\n  }\n\n  renderEanFilterNote();\n  syncEanHiddenInputs();\n};\n\nconst getCleanArchiveTitle = (heading: HTMLElement): string => {\n  const storedTitle = heading.dataset.archiveTitle?.trim();\n\n  if (storedTitle) {\n    return storedTitle;\n  }\n\n  const clone = heading.cloneNode(true) as HTMLElement;\n  clone.querySelector(\".c-product-listing-header__count\")?.remove();\n\n  return clone.textContent?.trim().replace(/\\s+/g, \" \") ?? \"\";\n};\n\nconst getArchiveCountText = (): string => {\n  const technicalCount = document\n    .querySelector<HTMLElement>(\n      \".woocommerce-products-header__title .c-product-listing-header__count\"\n    )\n    ?.textContent?.trim();\n\n  if (technicalCount) {\n    return technicalCount;\n  }\n\n  return `(${document.querySelectorAll(\".c-product-card\").length})`;\n};\n\nconst getArchiveTitleText = (): string => {\n  const sources = [\n    document.querySelector<HTMLElement>(\".c-product-listing-header\")?.dataset\n      .archiveTitle,\n    document.querySelector<HTMLElement>(\".c-product-listing-header__heading\")\n      ?.dataset.archiveTitle,\n    document.querySelector<HTMLElement>(\".woocommerce-products-header__title\")\n      ?.dataset.archiveTitle,\n  ];\n\n  for (const source of sources) {\n    const title = source?.trim();\n\n    if (title) {\n      return title;\n    }\n  }\n\n  const technicalTitle = document\n    .querySelector<HTMLElement>(\".woocommerce-products-header__title\")\n    ?.textContent?.trim()\n    .replace(/\\([^)]*\\)\\s*$/, \"\")\n    .replace(/\\s+/g, \" \");\n\n  if (technicalTitle) {\n    return technicalTitle;\n  }\n\n  return document.title.split(\" - \")[0]?.trim() ?? \"\";\n};\n\nconst ensureArchiveHeading = (): HTMLElement | null => {\n  const header = document.querySelector<HTMLElement>(\".c-product-listing-header\");\n\n  if (!header) {\n    return null;\n  }\n\n  let titleWrap = header.querySelector<HTMLElement>(\n    \".c-product-listing-header__title\"\n  );\n  const sort = header.querySelector<HTMLElement>(\".c-product-listing-header__sort\");\n\n  if (!titleWrap) {\n    titleWrap = document.createElement(\"div\");\n    titleWrap.className = \"c-product-listing-header__title\";\n\n    if (sort) {\n      header.insertBefore(titleWrap, sort);\n    } else {\n      header.prepend(titleWrap);\n    }\n  }\n\n  let heading = titleWrap.querySelector<HTMLElement>(\n    \".c-product-listing-header__heading\"\n  );\n\n  if (!heading) {\n    heading = document.createElement(\"h1\");\n    heading.className =\n      \"p-l fw-bold m-0 c-product-listing-header__heading p-brand\";\n    titleWrap.appendChild(heading);\n  }\n\n  const title = getArchiveTitleText();\n\n  if (title) {\n    header.dataset.archiveTitle = title;\n    heading.dataset.archiveTitle = title;\n  }\n\n  return heading;\n};\n\nconst stabilizeArchiveHeading = (): void => {\n  const ensuredHeading = ensureArchiveHeading();\n  const headings = Array.from(\n    document.querySelectorAll<HTMLElement>(\".c-product-listing-header__heading\")\n  );\n\n  if (ensuredHeading && !headings.includes(ensuredHeading)) {\n    headings.push(ensuredHeading);\n  }\n\n  headings.forEach((heading) => {\n    const title = getCleanArchiveTitle(heading);\n\n    if (!title) {\n      return;\n    }\n\n    const currentCount = heading\n      .querySelector<HTMLElement>(\".c-product-listing-header__count\")\n      ?.textContent?.trim();\n    const count = getArchiveCountText() || currentCount || \"(0)\";\n\n    heading.dataset.archiveTitle = title;\n    heading.textContent = `${title} `;\n\n    const countEl = document.createElement(\"span\");\n    countEl.className = \"c-product-listing-header__count fw-normal\";\n    countEl.textContent = count;\n\n    heading.appendChild(countEl);\n  });\n};\n\nconst initWcpfNotesDataGuard = (): void => {\n  const win = window as typeof window & {\n    jQuery?: JQueryLike;\n  };\n\n  if (\n    typeof win.jQuery !== \"function\" ||\n    !win.jQuery.fn?.data ||\n    document.body.dataset.wcpfNotesDataGuardInitialized === \"true\"\n  ) {\n    return;\n  }\n\n  document.body.dataset.wcpfNotesDataGuardInitialized = \"true\";\n\n  const originalData = win.jQuery.fn.data;\n\n  win.jQuery.fn.data = function patchedData(\n    this: { hasClass?: (className: string) => boolean },\n    key?: string | Record<string, unknown>,\n    value?: unknown\n  ) {\n    const result = originalData.apply(\n      this,\n      Array.from(arguments) as [string | Record<string, unknown> | undefined, unknown?]\n    );\n\n    if (\n      key === \"wcpf-note-entry\" &&\n      value === undefined &&\n      (!result || typeof result !== \"object\" || !(\"filterComponent\" in result)) &&\n      typeof this.hasClass === \"function\" &&\n      this.hasClass(\"c-wcpf-note-item\")\n    ) {\n      return {\n        filterComponent: {\n          entity: {\n            entityId: \"__inkospornova_missing_wcpf_note__\",\n          },\n        },\n      };\n    }\n\n    return result;\n  };\n};\n\nconst initWcpfNotesGuard = (): void => {\n  if (document.body.dataset.wcpfNotesGuardInitialized === \"true\") {\n    return;\n  }\n\n  initWcpfNotesDataGuard();\n  document.body.dataset.wcpfNotesGuardInitialized = \"true\";\n\n  const purgeBeforeWcpfInteraction = (event: Event): void => {\n    const target = event.target;\n\n    if (\n      target instanceof Element &&\n      target.closest(\".wcpf-filter, .wcpf-filter-notes, .wcpf-item, .wcpf-input\")\n    ) {\n      purgeStaleWcpfNotes();\n    }\n  };\n\n  [\"pointerdown\", \"mousedown\", \"click\", \"change\"].forEach((eventName) => {\n    document.addEventListener(eventName, purgeBeforeWcpfInteraction, true);\n  });\n\n  const win = window as typeof window & {\n    jQuery?: JQueryLike;\n  };\n\n  if (typeof win.jQuery === \"function\") {\n    win.jQuery(window).on(\n      \"wcpf_before_ajax_filtering wcpf_update_products wcpf_after_ajax_filtering\",\n      () => {\n        purgeStaleWcpfNotes();\n        window.requestAnimationFrame(stabilizeArchiveHeading);\n      }\n    );\n  }\n};\n\nexport const initArchiveFilters = (): void => {\n  if (typeof document === \"undefined\" || typeof window === \"undefined\") {\n    return;\n  }\n\n  const desktopSlot = document.querySelector<HTMLElement>(\n    \".js-product-filters-desktop-slot\"\n  );\n  const mobileSlot = document.querySelector<HTMLElement>(\n    \".js-product-filters-offcanvas-slot\"\n  );\n  const contentEl = document.querySelector<HTMLElement>(\n    \".js-product-filters-content\"\n  );\n  const offcanvasEl = document.getElementById(\"filtersOffcanvas\");\n\n  if (!desktopSlot || !mobileSlot || !contentEl || !offcanvasEl) {\n    initWcpfNotesGuard();\n    initEanFilterIntegration();\n    stabilizeArchiveHeading();\n    return;\n  }\n\n  const mediaQuery = window.matchMedia(DESKTOP_BREAKPOINT);\n\n  const syncFiltersLayout = (): void => {\n    if (mediaQuery.matches) {\n      hideOffcanvas(offcanvasEl);\n      moveFiltersContent(contentEl, desktopSlot);\n      return;\n    }\n\n    moveFiltersContent(contentEl, mobileSlot);\n  };\n\n  syncFiltersLayout();\n\n  if (typeof mediaQuery.addEventListener === \"function\") {\n    mediaQuery.addEventListener(\"change\", syncFiltersLayout);\n  } else {\n    mediaQuery.addListener(syncFiltersLayout);\n  }\n\n  offcanvasEl.addEventListener(\"hidden.bs.offcanvas\", syncFiltersLayout);\n\n  initWcpfNotesGuard();\n  initEanFilterIntegration();\n  stabilizeArchiveHeading();\n};\n","type JQueryWithWooNoticeScroll = {\n  scroll_to_notices?: (scrollElement?: unknown) => void;\n};\n\ntype WindowWithJQuery = typeof window & {\n  jQuery?: JQueryWithWooNoticeScroll;\n};\n\nconst disableWooCommerceNoticeScroll = (): void => {\n  const win = window as WindowWithJQuery;\n\n  if (!win.jQuery) {\n    return;\n  }\n\n  win.jQuery.scroll_to_notices = () => undefined;\n};\n\nexport const initWooCommerceNoticeScrollGuard = (): void => {\n  if (document.body.dataset.inkospornovaNoticeScrollGuardInitialized === \"true\") return;\n\n  document.body.dataset.inkospornovaNoticeScrollGuardInitialized = \"true\";\n\n  disableWooCommerceNoticeScroll();\n\n  window.setTimeout(disableWooCommerceNoticeScroll, 0);\n  window.setTimeout(disableWooCommerceNoticeScroll, 250);\n};\n","import { initFloatSidebars } from \"./float-sidebar\";\r\nimport { initLightGalleries } from \"./lightgallery\";\r\nimport { initSwipers } from \"./swiper\";\r\nimport { initFormHandlers } from \"./forms\"; \r\nimport { initAccordion } from \"./accordion\";\r\nimport { initHeader } from \"./header\";\r\nimport { initBootstrapCollapse } from \"./bootstrap\";\r\nimport { initBootstrapModal } from \"./bootstrap\";\r\nimport { initBootstrapTabs } from \"./bootstrap\";\r\nimport { initBootstrapTooltips } from \"./bootstrap\";\nimport { initBootstrapToasts } from \"./bootstrap\";\nimport { initToast } from \"./toast\";\nimport { initBootstrapPlaceholders } from \"./placeholders\";\nimport { initProductBottomBar } from \"./product-bottom-bar\";\nimport { initCartDrawer } from \"./cart-toggle\";\nimport { initArchiveFilters } from \"./archive-filters\";\nimport { initWooCommerceNoticeScrollGuard } from \"./woocommerce-notice-scroll\";\n\r\n\r\n\r\nconst initAll = () => {\r\n  initHeader();\r\n  initFloatSidebars();\r\n  initLightGalleries();\r\n  initSwipers();\r\n  initFormHandlers(); \r\n  initAccordion();\r\n  initBootstrapCollapse();\r\n  initBootstrapModal();\r\n  initBootstrapTabs();\n  initBootstrapTooltips();\n  initBootstrapToasts();\n  initBootstrapPlaceholders();\n  initProductBottomBar();\n  initCartDrawer();\n  initWooCommerceNoticeScrollGuard();\n  initArchiveFilters();\n  initToast();\n};\n\r\nconst setup = () => {\r\n  if (typeof document === \"undefined\") return;\r\n\r\n  if (document.readyState === \"loading\") {\r\n    document.addEventListener(\"DOMContentLoaded\", initAll);\r\n    return;\r\n  }\r\n\r\n  initAll();\r\n};\r\n\r\nsetup();\r\nexport { initHeader };\r\nexport { initFloatSidebars };\r\nexport { initLightGalleries };\r\nexport { initSwipers };\r\nexport { initFormHandlers }; \r\nexport { initBootstrapCollapse };\r\nexport { initBootstrapModal };\r\nexport { initBootstrapTabs };\r\nexport { initBootstrapTooltips };\r\nexport { initBootstrapToasts };\nexport { initToast };\nexport { initProductBottomBar };\nexport { initCartDrawer };\nexport { initArchiveFilters };\nexport { initWooCommerceNoticeScrollGuard };\nexport const isPatternlabWebpackReady = true;\n","export const initHeader = (): void => {\n  const header = document.querySelector<HTMLElement>('header') ?? document;\n  const primaryHeader = document.querySelector<HTMLElement>('.primaryHeader');\n  const mobileMenu = header.querySelector<HTMLElement>('.headerMenu');\n  const hamburger = header.querySelector<HTMLElement>('.headerMainHamburger .c-btn');\n  const closeMobileMenu = header.querySelector<HTMLElement>('#closeMobileMenu');\n\n  const infoItem = header.querySelector<HTMLLIElement>('.menu-item.has-submenu.info-item');\n  const trigger = infoItem?.querySelector<HTMLAnchorElement>('.blog-accordeon');\n  const wrapper = infoItem?.querySelector<HTMLElement>('.wrapper-subnav');\n  const submenu = infoItem?.querySelector<HTMLElement>('.subnav');\n  const iconDown = infoItem?.querySelector<HTMLElement>('.icon-minus');\n  const iconUp = infoItem?.querySelector<HTMLElement>('.icon-plus');\n\n  if (!infoItem || !trigger || !wrapper || !submenu) return;\n\n  const setOpen = (isOpen: boolean): void => {\n    infoItem.classList.toggle('--active', isOpen);\n    wrapper.classList.toggle('d-none', !isOpen);\n    submenu.classList.toggle('show', isOpen);\n    trigger.setAttribute('aria-expanded', String(isOpen));\n\n    iconDown?.classList.toggle('d-none', isOpen);\n    iconUp?.classList.toggle('d-none', !isOpen);\n  };\n\n  const isOpen = (): boolean => trigger.getAttribute('aria-expanded') === 'true';\n\n  setOpen(false);\n\n  trigger.addEventListener('click', (event: MouseEvent) => {\n    event.preventDefault();\n    setOpen(!isOpen());\n  });\n\n  document.addEventListener('click', (event: MouseEvent) => {\n    const target = event.target as Node | null;\n    if (!target || !isOpen() || infoItem.contains(target)) return;\n\n    setOpen(false);\n  });\n\n  document.addEventListener('keydown', (event: KeyboardEvent) => {\n    if (event.key === 'Escape' && isOpen()) {\n      setOpen(false);\n      trigger.focus();\n    }\n  });\n\n  const closeMobile = (): void => {\n    mobileMenu?.classList.remove('--showMobile');\n    mobileMenu?.setAttribute('aria-hidden', 'true');\n    hamburger?.setAttribute('aria-expanded', 'false');\n    primaryHeader?.classList.remove('--openMenu');\n  };\n\n  hamburger?.setAttribute('aria-controls', 'mobileMenu');\n  hamburger?.setAttribute('aria-expanded', 'false');\n\n  hamburger?.addEventListener('click', (event: MouseEvent) => {\n    event.preventDefault();\n    mobileMenu?.classList.add('--showMobile');\n    mobileMenu?.setAttribute('aria-hidden', 'false');\n    hamburger?.setAttribute('aria-expanded', 'true');\n    primaryHeader?.classList.add('--openMenu');\n  });\n\n  closeMobileMenu?.addEventListener('click', () => {\n    closeMobile();\n  });\n\n  document.addEventListener('keydown', (event: KeyboardEvent) => {\n    if (event.key === 'Escape' && mobileMenu?.classList.contains('--showMobile')) {\n      closeMobile();\n      hamburger?.focus();\n    }\n  });\n};\n","export const initAccordion = (): void => {\r\n\r\n    document.querySelectorAll<HTMLButtonElement>('.accordion-header.active').forEach(header => {\r\n      const content = header.nextElementSibling as HTMLElement | null;\r\n      if (content) {\r\n        content.style.maxHeight = content.scrollHeight + 16 + 'px';\r\n      }\r\n    });\r\n\r\n    // Obsługa kliknięcia na nagłówki accordion\r\n    document.querySelectorAll<HTMLButtonElement>('.accordion-header').forEach(header => {\r\n      header.addEventListener('click', () => {\r\n        const activeHeader = document.querySelector<HTMLButtonElement>('.accordion-header.active');\r\n\r\n        // Zamknij aktywny accordion, jeśli jest inny niż kliknięty\r\n        if (activeHeader && activeHeader !== header) {\r\n          activeHeader.classList.remove('active');\r\n          const activeContent = activeHeader.nextElementSibling as HTMLElement | null;\r\n          if (activeContent) {\r\n            activeContent.style.maxHeight = '0px'; // Zamknij zawartość\r\n          }\r\n        }\r\n\r\n        // Obsługa klikniętego nagłówka\r\n        const content = header.nextElementSibling as HTMLElement | null;\r\n        if (!content) return; // Guard clause\r\n        \r\n        header.classList.toggle('active');\r\n\r\n        if (header.classList.contains('active')) {\r\n          // Oblicz dynamiczną wysokość zawartości i dodaj 32px\r\n          content.style.maxHeight = content.scrollHeight + 32 + 'px';\r\n        } else {\r\n          content.style.maxHeight = '0px'; // Zamknij zawartość\r\n        }\r\n      });\r\n    });\r\n};","export const initBootstrapPlaceholders = (root: ParentNode = document): void => {\r\n  const wrappers = root.querySelectorAll<HTMLElement>(\"[data-placeholder-target]\");\r\n\r\n  wrappers.forEach((wrapper) => {\r\n    const isLoaded = wrapper.dataset.loaded === \"true\";\r\n\r\n    const placeholders = wrapper.querySelectorAll<HTMLElement>(\"[data-placeholder]\");\r\n    const content = wrapper.querySelectorAll<HTMLElement>(\"[data-content]\");\r\n\r\n    placeholders.forEach((el) => {\r\n      el.classList.toggle(\"d-none\", isLoaded);\r\n      el.setAttribute(\"aria-hidden\", isLoaded ? \"true\" : \"false\");\r\n    });\r\n\r\n    content.forEach((el) => {\r\n      el.classList.toggle(\"d-none\", !isLoaded);\r\n    });\r\n  });\r\n};\r\n\r\nexport const setPlaceholderLoaded = (\r\n  target: HTMLElement,\r\n  loaded: boolean\r\n): void => {\r\n  target.dataset.loaded = loaded ? \"true\" : \"false\";\r\n  initBootstrapPlaceholders(target);\r\n};"],"names":["module","exports","t","Map","e","set","i","n","has","s","get","size","console","error","Array","from","keys","remove","delete","window","CSS","escape","replace","dispatchEvent","Event","o","jquery","nodeType","r","length","document","querySelector","a","getClientRects","getComputedStyle","getPropertyValue","closest","parentNode","l","Node","ELEMENT_NODE","classList","contains","disabled","hasAttribute","getAttribute","c","documentElement","attachShadow","getRootNode","ShadowRoot","h","d","offsetHeight","u","jQuery","body","f","p","dir","m","NAME","fn","jQueryInterface","Constructor","noConflict","readyState","addEventListener","push","g","_","transitionDuration","transitionDelay","Number","parseFloat","split","target","removeEventListener","setTimeout","b","indexOf","Math","max","min","v","y","w","A","E","T","mouseenter","mouseleave","C","Set","O","uidEvent","x","k","Object","values","find","callable","delegationSelector","L","I","S","relatedTarget","delegateTarget","call","this","oneOff","querySelectorAll","P","N","off","type","apply","D","Boolean","$","entries","includes","on","one","startsWith","slice","trigger","isPropagationStopped","isImmediatePropagationStopped","isDefaultPrevented","bubbles","cancelable","preventDefault","defaultPrevented","defineProperty","configurable","j","toString","JSON","parse","decodeURIComponent","M","toLowerCase","F","setDataAttribute","setAttribute","removeDataAttribute","removeAttribute","getDataAttributes","dataset","filter","charAt","getDataAttribute","H","Default","DefaultType","Error","_getConfig","_mergeConfigObj","_configAfterMerge","_typeCheckConfig","constructor","prototype","match","RegExp","test","TypeError","toUpperCase","W","super","_element","_config","DATA_KEY","dispose","EVENT_KEY","getOwnPropertyNames","_queueCallback","getInstance","getOrCreateInstance","VERSION","eventName","B","trim","map","join","z","concat","Element","findOne","children","matches","parents"